actor Pool<T> {
    private var idle: [T]
    private var waiters: [CheckedContinuation<T, Never>] = []
    init(_ items: [T]) { idle = items }

    func acquire() async -> T {          // pop, create, or suspend on a waiter
        if idle.isEmpty { return create() }
        return idle.removeLast()
    }
    func release(_ item: T) { idle.append(item) }
}
